  text-align: left;
}

.sidebar-brand-mark {
  width: 44px;
  height: 44px;
  display: grid;
  place-items: center;
  border-radius: 14px;
  background: linear-gradient(135deg, rgba(172, 206, 234, 0.55), rgba(255, 233, 137, 0.45));
  font-family: var(--font-ui);
  font-weight: 700;
}

.sidebar-brand-copy {
  display: flex;
  flex-direction: column;
  gap: 2px;
  font-family: var(--font-ui);
}

.sidebar-brand-copy span {
  color: var(--text-muted);
  font-size: var(--text-sm);
}

.sidebar-nav {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.sidebar-nav-item {
  border: 0;
  border-radius: var(--radius-md);
  background: transparent;
  color: inherit;
  padding: 10px 12px;
  display: flex;
  align-items: center;
  gap: 10px;
  text-align: left;
  transition: background var(--motion-normal) var(--ease-standard);
}

.sidebar-nav-item:hover,
.sidebar-nav-item.is-active {
  background: rgba(172, 206, 234, 0.18);
}

.sidebar-nav-dot {
  width: 8px;
  height: 8px;
  border-radius: 999px;
  background: rgba(100, 116, 139, 0.45);
}

.sidebar-nav-item.is-active .sidebar-nav-dot {
  background: var(--brand-blue);
}

.sidebar-task-card,
.sidebar-history,
.sidebar-credits,
.sidebar-user {
  border-radius: var(--radius-lg);
  padding: 14px;
  background: rgba(255, 255, 255, 0.56);
  border: 1px solid var(--border-subtle);
}

.sidebar-task-card p,
.sidebar-history-item,
.sidebar-credits span,
.sidebar-user span {
  margin: 6px 0 0;
  color: var(--text-muted);
  font-size: var(--text-sm);
  line-height: var(--line-height-reading);
}

.sidebar-history {
  display: grid;
  gap: 10px;
}

.sidebar-footer {
  margin-top: auto;
  display: grid;
  gap: 12px;
}

.sidebar-user {
  display: flex;
  align-items: center;
  gap: 12px;
}

.sidebar-avatar {
  width: 38px;
  height: 38px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  font-family: var(--font-ui);
  font-size: var(--text-sm);
  background: rgba(172, 206, 234, 0.22);
}

.home-main {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: calc(100vh - 40px);
}

.home-content {
  width: min(960px, 100%);
  display: grid;
  gap: 24px;
  padding: 24px 8px 56px;
}

.home-content h1 {
  margin: 0;
  font-family: var(--font-ui);
  font-size: clamp(2.3rem, 5vw, 4.25rem);
  line-height: 1.02;
  max-width: 10ch;
}

.home-subtitle {
  margin: 0;
  max-width: 62ch;
  color: var(--text-muted);
  font-size: var(--text-md);
  line-height: var(--line-height-reading);
}

.mode-selector-panel {
  display: grid;
  gap: 10px;
}

.mode-selector-track {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 8px;
}

.mode-step {
  border: 0;
  background: transparent;
  padding: 0;
  display: grid;
  gap: 10px;
  text-align: left;
  position: relative;
}

.mode-step-node {
  width: 14px;
  height: 14px;
  border-radius: 50%;
  background: rgba(100, 116, 139, 0.22);
  border: 1px solid rgba(100, 116, 139, 0.18);
}

.mode-step-copy {
  display: grid;
  gap: 4px;
  padding: 14px;
  border-radius: var(--radius-lg);
  background: rgba(255, 255, 255, 0.52);
  border: 1px solid var(--border-subtle);
  min-height: 106px;
}

.mode-step-copy strong {
  font-family: var(--font-ui);
}

.mode-step-copy small {
  color: var(--text-muted);
  font-size: var(--text-sm);
  line-height: 1.45;
}

.mode-step-connector {
  position: absolute;
  left: 15px;
  right: -7px;
  top: 6px;
  height: 1px;
  background: rgba(100, 116, 139, 0.18);
  z-index: -1;
}

.mode-step.is-active .mode-step-node {
  background: rgba(172, 206, 234, 0.85);
  border-color: rgba(172, 206, 234, 0.95);
  box-shadow: 0 0 0 6px rgba(172, 206, 234, 0.14);
}

.mode-step.is-active .mode-step-copy {
  background: rgba(172, 206, 234, 0.14);
  border-color: rgba(172, 206, 234, 0.38);
}

.home-input-card {
  border-radius: 28px;
  padding: 22px;
  display: grid;
  gap: 16px;
}

.input-card-header,
.input-card-footer,
.workspace-meta,
.process-meta,
.stage-heading,
.detail-title-row,
.tool-block-header,
.workspace-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
}

.tertiary-action,
.icon-button,
.sidebar-brand,
.example-task-card,
.process-stage,
.tool-block {
  transition:
    transform var(--motion-fast) var(--ease-standard),
    background var(--motion-normal) var(--ease-standard),
    border-color var(--motion-normal) var(--ease-standard);
}

.tertiary-action {
  border: 0;
  background: transparent;
  color: var(--text-muted);
}

.home-textarea {
  width: 100%;
  resize: vertical;
  min-height: 168px;
  border: 0;
  border-radius: var(--radius-lg);
  padding: 20px;
  background: rgba(255, 255, 255, 0.66);
  line-height: var(--line-height-reading);
  box-shadow: inset 0 0 0 1px rgba(15, 23, 42, 0.04);
}

.input-actions,
.chip-row,
.citation-row,
.file-chip-row,
.approval-actions,
.draft-actions,
.action-message-row {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}

.icon-button {
  width: 42px;
  height: 42px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  border: 1px solid var(--border-subtle);
  background: rgba(255, 255, 255, 0.65);
  color: var(--text-main);
}

.icon-button:hover,
.example-task-card:hover,
.tool-block:hover,
.process-stage:hover {
  transform: translateY(-1px);
}

.icon {
  width: 18px;
  height: 18px;
}

.button-primary,
.button-secondary {
  border: 0;
  border-radius: var(--radius-pill);
  padding: 11px 18px;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-family: var(--font-ui);
}

.button-primary {
  background: var(--text-main);
  color: #fff;
}

.button-secondary {
  background: rgba(255, 255, 255, 0.75);
  color: var(--text-main);
  border: 1px solid var(--border-subtle);
}

.send-button {
  margin-left: auto;
}

.inline-notice {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  width: fit-content;
  padding: 8px 12px;
  border-radius: var(--radius-pill);
  background: rgba(224, 242, 241, 0.9);
  color: #34515a;
  font-size: var(--text-sm);
}

.dropzone-card {
  border-radius: var(--radius-lg);
  border: 1px dashed rgba(100, 116, 139, 0.28);
  padding: 14px 16px;
  display: flex;
  align-items: center;
  gap: 12px;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.72), rgba(224, 242, 241, 0.52)),
    url("/noise.svg");
}

.dropzone-card p {
  margin: 4px 0 0;
  color: var(--text-muted);
  font-size: var(--text-sm);
}

.file-chip {
  display: grid;
  gap: 4px;
  padding: 10px 12px;
  border-radius: var(--radius-md);
  background: rgba(255, 255, 255, 0.78);
  border: 1px solid var(--border-subtle);
}

.file-chip span {
  color: var(--text-muted);
  font-size: var(--text-xs);
}

.example-task-section {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 12px;
}

.example-task-card {
  padding: 14px 16px;
  border-radius: var(--radius-lg);
  border: 1px solid var(--border-subtle);
  background: rgba(255, 255, 255, 0.72);
  text-align: left;
  line-height: 1.5;
}

.workspace-shell {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 330px;
  gap: 20px;
  position: relative;
  padding-bottom: 180px;
}

.workspace-main-column {
  display: grid;
  gap: 18px;
}

.workspace-header {
  display: grid;
  gap: 16px;
}

.workspace-meta {
  padding: 16px 18px;
  border-radius: var(--radius-lg);
}

.workspace-meta > div {
  display: grid;
  gap: 4px;
}

.workspace-heading {
  align-items: flex-start;
}

.workspace-heading h1 {
  margin: 4px 0 8px;
  font-family: var(--font-ui);
  font-size: clamp(1.6rem, 2.3vw, 2.4rem);
  line-height: 1.15;
}

.workspace-heading p {
  margin: 0;
  color: var(--text-muted);
  max-width: 62ch;
}

.process-card {
  border-radius: var(--radius-lg);
  padding: 18px;
  display: grid;
  gap: 16px;
}

.process-status-stack {
  display: flex;
  align-items: center;
  gap: 10px;
  color: var(--text-muted);
}

.process-track {
  position: relative;
  padding-top: 10px;
}

.process-track-base,
.process-track-fill {
  position: absolute;
  left: 0;
  right: 0;
  top: 16px;
  height: 4px;
  border-radius: var(--radius-pill);
}

.process-track-base {
  background: rgba(0, 0, 0, 0.06);
}

.process-track-fill {
  right: auto;
  background: var(--gradient-progress);
}

.process-stage-row {
  display: grid;
  grid-template-columns: repeat(7, minmax(124px, 1fr));
  gap: 12px;
  overflow-x: auto;
  padding-bottom: 8px;
}

.process-stage {
  position: relative;
  z-index: 1;
  display: grid;
  gap: 10px;
  padding: 0;
  border: 0;
  background: transparent;
  text-align: left;
}

.process-stage-dot {
  width: 16px;
  height: 16px;
  border-radius: 50%;
  border: 2px solid rgba(100, 116, 139, 0.2);
  background: #fff;
}

.process-stage-copy {
  display: grid;
  gap: 4px;
  padding: 10px 12px;
  border-radius: var(--radius-md);
  background: rgba(255, 255, 255, 0.68);
  border: 1px solid var(--border-subtle);
  min-height: 100px;
}

.process-stage-copy strong {
  font-family: var(--font-ui);
}

.process-stage-copy small {
  color: var(--text-muted);
  line-height: 1.45;
}

.process-stage.is-current .process-stage-dot,
.process-stage.is-running .process-stage-dot,
.process-stage.is-waiting .process-stage-dot,
.process-stage.is-completed .process-stage-dot {
  background: var(--brand-blue);
  border-color: rgba(172, 206, 234, 0.92);
}

.process-stage.is-completed .process-stage-copy {
  background: rgba(224, 242, 241, 0.6);
}

.process-stage.is-current .process-stage-copy,
.process-stage.is-running .process-stage-copy,
.process-stage.is-waiting .process-stage-copy {
  border-color: rgba(172, 206, 234, 0.4);
}

.stream-layout {
  display: grid;
  gap: 18px;
}

.stage-section {
  display: grid;
  gap: 14px;
}

.stage-heading {
  align-items: flex-end;
}

.stage-heading h2,
.detail-header h2 {
  margin: 4px 0 0;
  font-family: var(--font-ui);
  font-size: var(--text-xl);
}

.stream-placeholder,
.stream-item,
.detail-panel,
.agent-control {
  border-radius: var(--radius-lg);
}

.stream-placeholder,
.stream-item {
  padding: 16px;
}

.stream-placeholder p {
  margin: 6px 0 0;
  color: var(--text-muted);
}

.stream-item {
  display: grid;
  gap: 14px;
}

.stream-item-meta {
  display: flex;
  align-items: center;
  gap: 12px;
  justify-content: space-between;
}

.stream-item-time {
  color: var(--text-muted);
  font-size: var(--text-sm);
}

.stream-item-body {
  display: grid;
  gap: 14px;
}

.stream-item-body h3,
.output-card h3,
.detail-title-row strong {
  margin: 0;
  font-family: var(--font-ui);
}

.stream-item-body p,
.output-card p,
.detail-content p,
.compact-list,
.detail-content pre {
  margin: 0;
  color: var(--text-muted);
  line-height: var(--line-height-reading);
}

.status-pill {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  width: fit-content;
  padding: 7px 10px;
  border-radius: var(--radius-pill);
  font-size: var(--text-xs);
  text-transform: capitalize;
  border: 1px solid transparent;
}

.status-pill.is-done,
.status-pill.is-ready,
.status-pill.is-completed,
.status-pill.is-accepted {
  background: rgba(224, 242, 241, 0.92);
  color: #32555b;
}

.status-pill.is-running {
  background: rgba(172, 206, 234, 0.2);
  color: #355e7a;
}

.status-pill.is-waiting,
.status-pill.is-waiting-for-human,
.status-pill.is-waiting-for-human-approval,
.status-pill.is-waiting-for-human,
.status-pill.is-revision-requested {
  background: rgba(255, 233, 137, 0.36);
  color: #745c17;
}

.status-pill.is-needs-review,
.status-pill.is-blocked,
.status-pill.is-rejected {
  background: rgba(255, 146, 112, 0.22);
  color: #8a4c2e;
}

.status-pill.is-upcoming {
  background: rgba(148, 163, 184, 0.14);
  color: var(--text-muted);
}

.source-chip,
.citation-chip,
.fit-pill,
.rank-chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 7px 10px;
  border-radius: var(--radius-pill);
  font-size: var(--text-xs);
  background: rgba(255, 255, 255, 0.72);
  border: 1px solid var(--border-subtle);
}

.tool-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 12px;
}

.tool-block {
  padding: 14px;
  border-radius: var(--radius-lg);
  border: 1px solid var(--border-subtle);
  background: rgba(255, 255, 255, 0.76);
  text-align: left;
  display: grid;
  gap: 10px;
}

.tool-block p,
.tool-block-time {
  margin: 0;
  color: var(--text-muted);
  font-size: var(--text-sm);
}

.tool-block.is-selected {
  border-color: rgba(172, 206, 234, 0.55);
  background: rgba(172, 206, 234, 0.12);
}

.output-card {
  margin-top: 4px;
  padding: 18px;
  display: grid;
  gap: 18px;
}

.output-card-header {
  display: grid;
  gap: 8px;
}

.output-card-header p {
  max-width: 58ch;
}

.opportunity-grid,
.literature-layout,
.compact-output-grid,
.venue-grid {
  display: grid;
  gap: 14px;
}

.opportunity-grid {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.opportunity-card,
.venue-card {
  border-radius: var(--radius-lg);
  padding: 16px;
  background: rgba(255, 255, 255, 0.72);
  border: 1px solid var(--border-subtle);
  display: grid;
  gap: 10px;
}

.opportunity-card h4,
.output-card h4 {
  margin: 0;
  font-family: var(--font-ui);
}

.opportunity-topline,
.metric-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}

.metric-row {
  color: var(--text-muted);
  font-size: var(--text-sm);
}

.detail-grid {
  display: grid;
  gap: 10px;
  margin: 0;
}

.detail-grid dt {
  font-family: var(--font-ui);
  font-size: var(--text-xs);
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--text-soft);
}

.detail-grid dd {
  margin: 4px 0 0;
  color: var(--text-muted);
}

.compact-list {
  padding-left: 18px;
}

.compact-list li + li {
  margin-top: 8px;
}

.literature-layout,
.compact-output-grid {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.approval-recommendation,
.abstract-title {
  padding: 14px 16px;
  border-radius: var(--radius-lg);
  background: rgba(172, 206, 234, 0.12);
  border: 1px solid rgba(172, 206, 234, 0.2);
  color: #27475f;
}

.approval-status {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.abstract-body {
  color: var(--text-main);
  font-size: var(--text-md);
}

.venue-grid {
  grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
}

.fit-pill.fit-high-potential,
.fit-pill.fit-strong {
  background: rgba(224, 242, 241, 0.94);
  color: #32555b;
}

.fit-pill.fit-promising,
.fit-pill.fit-good {
  background: rgba(172, 206, 234, 0.24);
  color: #355e7a;
}

.fit-pill.fit-niche,
.fit-pill.fit-reach {
  background: rgba(255, 233, 137, 0.34);
  color: #775b17;
}

.detail-panel {
  position: sticky;
  top: 20px;
  padding: 18px;
  display: grid;
  gap: 16px;
}

.detail-empty {
  padding: 16px;
  border-radius: var(--radius-lg);
  background: rgba(255, 255, 255, 0.7);
  color: var(--text-muted);
}

.detail-content {
  display: grid;
  gap: 16px;
}

.detail-section {
  display: grid;
  gap: 8px;
}

.detail-section pre {
  padding: 14px;
  border-radius: var(--radius-lg);
  background: var(--code-bg);
  color: var(--code-text);
  font-family: var(--font-mono);
  font-size: var(--text-sm);
  overflow: auto;
}

.citation-list {
  display: grid;
  gap: 8px;
}

.citation-list-item {
  padding: 10px 12px;
  border-radius: var(--radius-md);
  background: rgba(255, 255, 255, 0.72);
  border: 1px solid var(--border-subtle);
  color: var(--text-muted);
}

.agent-control {
  position: fixed;
  right: 26px;
  bottom: 24px;
  width: min(760px, calc(100vw - 72px));
  padding: 16px;
  display: grid;
  gap: 14px;
  z-index: 10;
}

.agent-control-top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
}

.agent-control-top p {
  margin: 4px 0 0;
  color: var(--text-muted);
  font-size: var(--text-sm);
}

.toggle-group {
  display: inline-flex;
  gap: 4px;
  padding: 4px;
  border-radius: var(--radius-pill);
  background: rgba(255, 255, 255, 0.72);
  border: 1px solid var(--border-subtle);
}

.toggle-group button {
  border: 0;
  background: transparent;
  border-radius: var(--radius-pill);
  padding: 8px 12px;
  color: var(--text-muted);
}

.toggle-group button.is-active {
  background: rgba(172, 206, 234, 0.22);
  color: var(--text-main);
}

.agent-input-row {
  display: grid;
  grid-template-columns: 42px 42px minmax(0, 1fr) auto;
  gap: 10px;
}

.agent-input-row input {
  border: 1px solid var(--border-subtle);
  background: rgba(255, 255, 255, 0.72);
  border-radius: var(--radius-pill);
  padding: 0 16px;
}

.compact-drop {
  padding: 12px 14px;
}

.is-listening {
  position: relative;
}

.is-listening::before {
  content: "";
  position: absolute;
  inset: -6px;
  z-index: -1;
  border-radius: inherit;
  background: var(--gradient-progress);
  filter: blur(24px);
  opacity: 0.18;
  animation: aurora-breathe 3.6s ease-in-out infinite;
}

.is-listening::after {
  content: "";
  position: absolute;
  inset: -6px;
  z-index: -1;
  border-radius: inherit;
  opacity: 0.1;
  pointer-events: none;
  background-image: url("/noise.svg");
  mix-blend-mode: soft-light;
  animation: grain-shift 4s steps(6) infinite;
}

@keyframes aurora-breathe {
  0%,
  100% {
    opacity: 0.14;
    transform: scale(0.98);
  }
  50% {
    opacity: 0.26;
    transform: scale(1.015);
  }
}

@keyframes grain-shift {
  0% {
    transform: translate(0, 0);
  }
  25% {
    transform: translate(-1%, 1%);
  }
  50% {
    transform: translate(1%, -1%);
  }
  75% {
    transform: translate(-0.5%, -1%);
  }
  100% {
    transform: translate(0, 0);
  }
}

@media (max-width: 1280px) {
  .workspace-shell {
    grid-template-columns: minmax(0, 1fr);
  }

  .detail-panel {
    position: static;
  }
}

@media (max-width: 1080px) {
  .app-shell.is-home,
  .app-shell.is-running {
    grid-template-columns: 220px minmax(0, 1fr);
  }

  .example-task-section,
  .mode-selector-track {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .opportunity-grid,
  .literature-layout,
  .compact-output-grid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 840px) {
  .app-shell {
    grid-template-columns: 1fr;
    padding: 14px;
  }

