import { useState } from 'react';
import type { ControlMode, UploadedFile } from '../types/workflow';
import { Icon } from './Icon';

interface AgentControlProps {
  controlMode: ControlMode;
  uploadedFiles: UploadedFile[];
  onModeChange: (mode: ControlMode) => void;
  onSimulateUpload: () => Promise<void>;
}

export function AgentControl({
  controlMode,
  uploadedFiles,
  onModeChange,
  onSimulateUpload,
}: AgentControlProps) {
  const [isListening, setIsListening] = useState(false);
  const [input, setInput] = useState('');
  const [showDropState, setShowDropState] = useState(false);
  const [localNotice, setLocalNotice] = useState<string | null>(null);

  function handleVoiceCapture() {
    if (isListening) {
      return;
    }

    setIsListening(true);
    setLocalNotice('Listening…');

    window.setTimeout(() => {
      setInput('Can you tighten the benchmark framing before we draft the introduction?');
      setLocalNotice('Voice note transcribed.');
      setIsListening(false);
    }, 1400);
  }

  async function handleUpload() {
    setShowDropState(true);
    setLocalNotice('Drag and drop paper into the control lane.');
    await onSimulateUpload();
    window.setTimeout(() => setShowDropState(false), 2500);
  }

  function handleSend() {
    setLocalNotice('Follow-up queued for the research agent.');
    setInput('');
  }

  return (
    <section className={`agent-control glass-surface ${isListening ? 'is-listening' : ''}`}>
      <div className="agent-control-top">
        <div>
          <span className="eyebrow">Research Agent status</span>
          <strong>live</strong>
          <p>
            {controlMode === 'automation'
              ? 'Full Automation: continues until approval gates.'
              : 'Discuss: asks for clarification before major steps.'}
          </p>
        </div>

        <div className="toggle-group" role="tablist" aria-label="Agent mode">
          <button
            className={controlMode === 'automation' ? 'is-active' : ''}
            onClick={() => onModeChange('automation')}
            type="button"
          >
            Full Automation
          </button>
          <button
            className={controlMode === 'discuss' ? 'is-active' : ''}
            onClick={() => onModeChange('discuss')}
            type="button"
          >
            Discuss
          </button>
        </div>
      </div>

      <div className="agent-input-row">
        <button className="icon-button" onClick={handleVoiceCapture} type="button">
          <Icon className="icon" name="mic" />
        </button>
        <button className="icon-button" onClick={handleUpload} type="button">
          <Icon className="icon" name="upload" />
        </button>
        <input
          onChange={(event) => setInput(event.target.value)}
          placeholder="Discover more / Ask follow-up…"
          value={input}
        />
        <button className="button-primary" onClick={handleSend} type="button">
          <Icon className="icon" name="send" />
          <span>Send</span>
        </button>
      </div>

      {showDropState ? (
        <div className="dropzone-card compact-drop">
          <Icon className="icon" name="drag" />
          <div>
            <strong>Drag and drop paper</strong>
            <p>Simulated upload state for follow-up files and notes.</p>
          </div>
        </div>
      ) : null}

      {uploadedFiles.length ? (
        <div className="file-chip-row">
          {uploadedFiles.slice(-2).map((file) => (
            <div className="file-chip" key={file.id}>
              <strong>{file.name}</strong>
              <span>{file.status}</span>
            </div>
          ))}
        </div>
      ) : null}

      {localNotice ? <div className="inline-notice">{localNotice}</div> : null}
    </section>
  );
}

import { useEffect, useState } from 'react';
import type { ToolBlock, ToolDetail } from '../types/tools';
import type {
  AgentRun,
  ControlMode,
  StreamEvent,
  UploadedFile,
  WorkflowStage,
} from '../types/workflow';
import { formatDuration } from '../utils/format';
import { AgentControl } from './AgentControl';
import { AgentStream } from './AgentStream';
import { DetailPanel } from './DetailPanel';
import { ProcessBar } from './ProcessBar';

interface RunningWorkspaceProps {
  run: AgentRun;
  stages: WorkflowStage[];
  events: StreamEvent[];
  selectedToolId: string | null;
  selectedToolDetail: ToolDetail | null;
  uploadedFiles: UploadedFile[];
  controlMode: ControlMode;
  actionMessages: {
    pdf?: string;
    overleaf?: string;
    phone?: string;
  };
  onSelectTool: (block: ToolBlock) => void;
  onApprovalAction: (action: 'accept' | 'reject' | 'ask-revision', gateId: string) => void;
  onControlModeChange: (mode: ControlMode) => void;
  onSimulateUpload: () => Promise<void>;
  onPreparePdf: () => void;
  onPrepareOverleaf: () => void;
  onSendToPhone: () => void;
}

export function RunningWorkspace({
  run,
  stages,
  events,
  selectedToolId,
  selectedToolDetail,
  uploadedFiles,
  controlMode,
  actionMessages,
  onSelectTool,
  onApprovalAction,
  onControlModeChange,
  onSimulateUpload,
  onPreparePdf,
  onPrepareOverleaf,
  onSendToPhone,
}: RunningWorkspaceProps) {
  const [elapsedMs, setElapsedMs] = useState(Date.now() - new Date(run.startedAt).getTime());
  const [sectionRefs, setSectionRefs] = useState<Record<string, HTMLElement | null>>({});

  useEffect(() => {
    const interval = window.setInterval(() => {
      setElapsedMs(Date.now() - new Date(run.startedAt).getTime());
    }, 1000);

    return () => window.clearInterval(interval);
  }, [run.startedAt]);

  function handleStageSelect(stageId: string) {
    sectionRefs[stageId]?.scrollIntoView({ behavior: 'smooth', block: 'start' });
  }

  function handleRegisterSection(stageId: string, element: HTMLElement | null) {
    setSectionRefs((current) => {
      if (current[stageId] === element) {
        return current;
      }

      return {
        ...current,
        [stageId]: element,
      };
    });
  }

  const currentStage = stages.find((stage) => stage.id === run.currentStageId) ?? stages[0];

  return (
    <section className="workspace-shell">
      <div className="workspace-main-column">
        <header className="workspace-header">
          <div className="workspace-meta glass-surface">
            <div>
              <span className="eyebrow">Current mode</span>
              <strong>{run.mode}</strong>
            </div>
            <div>
              <span className="eyebrow">Used credits</span>
              <strong>{run.usedCredits}</strong>
            </div>
            <div>
              <span className="eyebrow">Time elapsed</span>
              <strong>{formatDuration(elapsedMs)}</strong>
            </div>
            <div>
              <span className="eyebrow">Task status</span>
              <strong>{run.status}</strong>
            </div>
          </div>

          <div className="workspace-heading">
            <div>
              <span className="eyebrow">Current task</span>
              <h1>{run.taskInput}</h1>
              <p>{currentStage?.description}</p>
            </div>
          </div>

          <ProcessBar
            currentStageId={run.currentStageId}
            elapsedLabel={formatDuration(elapsedMs)}
            onStageSelect={handleStageSelect}
            runStatus={run.status}
            stages={stages}
          />
        </header>

        <AgentStream
          actionMessages={actionMessages}
          events={events}
          onApprovalAction={onApprovalAction}
          onPrepareOverleaf={onPrepareOverleaf}
          onPreparePdf={onPreparePdf}
          onRegisterSection={handleRegisterSection}
          onSendToPhone={onSendToPhone}
          onToolSelect={onSelectTool}
          sectionRefs={sectionRefs}
          selectedToolId={selectedToolId}
          stages={stages}
        />
      </div>

      <div className="workspace-side-column">
        <DetailPanel detail={selectedToolDetail} />
      </div>

      <AgentControl
        controlMode={controlMode}
        onModeChange={onControlModeChange}
        onSimulateUpload={onSimulateUpload}
        uploadedFiles={uploadedFiles}
      />
    </section>
  );
}

import type { ToolBlock as ToolBlockType } from '../types/tools';
import type { StreamEvent, WorkflowStage } from '../types/workflow';
import { StreamItem } from './StreamItem';

interface AgentStreamProps {
  stages: WorkflowStage[];
  events: StreamEvent[];
  selectedToolId: string | null;
  actionMessages: {
    pdf?: string;
    overleaf?: string;
    phone?: string;
  };
  sectionRefs: Record<string, HTMLElement | null>;
  onToolSelect: (block: ToolBlockType) => void;
  onApprovalAction: (action: 'accept' | 'reject' | 'ask-revision', gateId: string) => void;
  onPreparePdf: () => void;
  onPrepareOverleaf: () => void;
  onSendToPhone: () => void;
  onRegisterSection: (stageId: string, element: HTMLElement | null) => void;
}

export function AgentStream({
  stages,
  events,
  selectedToolId,
  actionMessages,
  onToolSelect,
  onApprovalAction,
  onPreparePdf,
  onPrepareOverleaf,
  onSendToPhone,
  onRegisterSection,
}: AgentStreamProps) {
  return (
    <div className="stream-layout">
      {stages.map((stage) => {
        const stageEvents = events.filter((event) => event.stageId === stage.id);

        return (
          <section
            className="stage-section"
            id={`stage-${stage.id}`}
            key={stage.id}
            ref={(element) => onRegisterSection(stage.id, element)}
          >
            <div className="stage-heading">
              <div>
                <span className="eyebrow">{stage.shortLabel}</span>
                <h2>{stage.label}</h2>
              </div>
              <span className={`status-pill is-${stage.status}`}>{stage.status}</span>
            </div>

            {stageEvents.length ? (
              stageEvents.map((event) => (
                <StreamItem
                  actionMessages={actionMessages}
                  event={event}
                  key={event.id}
                  onApprovalAction={onApprovalAction}
                  onPrepareOverleaf={onPrepareOverleaf}
                  onPreparePdf={onPreparePdf}
                  onSendToPhone={onSendToPhone}
                  onToolSelect={onToolSelect}
                  selectedToolId={selectedToolId}
                />
              ))
            ) : (
              <div className="stream-placeholder glass-surface">
                <strong>{stage.description}</strong>
                <p>
                  {stage.status === 'upcoming'
                    ? 'Queued until upstream research steps finish.'
                    : 'This stage is active and waiting for the next agent event.'}
                </p>
              </div>
            )}
          </section>
        );
      })}
    </div>
  );
}

import type { ToolDetail } from '../types/tools';

interface DetailPanelProps {
  detail: ToolDetail | null;
}

export function DetailPanel({ detail }: DetailPanelProps) {
  return (
    <aside className="detail-panel glass-surface">
      <div className="detail-header">
        <span className="eyebrow">Detail</span>
        <h2>Detail</h2>
      </div>

      {!detail ? (
        <div className="detail-empty">
          Click a tool block to view the full information.
        </div>
      ) : (
        <div className="detail-content">
          <div className="detail-title-row">
            <strong>{detail.name}</strong>
            <span className={`status-pill is-${detail.status}`}>{detail.status}</span>
          </div>
          <div className="detail-section">
            <span className="eyebrow">Time used</span>
            <p>{detail.timeUsedLabel}</p>
          </div>
          <div className="detail-section">
            <span className="eyebrow">Input</span>
            <pre>{JSON.stringify(detail.inputPreview, null, 2)}</pre>
          </div>
          <div className="detail-section">
            <span className="eyebrow">Output</span>
            <pre>{JSON.stringify(detail.outputPreview, null, 2)}</pre>
          </div>
          <div className="detail-section">
            <span className="eyebrow">Sources</span>
            <div className="chip-row">
              {detail.sources.map((source) => (
                <span className="source-chip" key={source.id}>
                  {source.label}
                </span>
              ))}
            </div>
          </div>
          <div className="detail-section">
            <span className="eyebrow">Citations</span>
            <div className="citation-list">
              {detail.citations.length ? (
                detail.citations.map((citation) => (
                  <div className="citation-list-item" key={citation.id}>
                    {citation.title} ({citation.venue} {citation.year})
                  </div>
                ))
              ) : (
                <p>No linked citations for this tool.</p>
              )}
            </div>
          </div>
        </div>
      )}
    </aside>
  );
}

